import torch, torch.nn as nn
def lp_ft(backbone, head, loader, lp_epochs=5, ft_epochs=3):
    lossf = nn.CrossEntropyLoss()
    # 1단계 LP: 표현 얼리고 헤드만
    for p in backbone.parameters(): p.requires_grad_(False)
    opt = torch.optim.AdamW(head.parameters(), lr=1e-2)
    for _ in range(lp_epochs):
        for x, y in loader:
            loss = lossf(head(backbone(x)), y)
            opt.zero_grad(); loss.backward(); opt.step()
    # 2단계 FT: 전부 풀고 작은 학습률로
    for p in backbone.parameters(): p.requires_grad_(True)
    opt = torch.optim.AdamW(list(backbone.parameters()) + list(head.parameters()), lr=1e-5)
    for _ in range(ft_epochs):
        for x, y in loader:
            loss = lossf(head(backbone(x)), y)
            opt.zero_grad(); loss.backward(); opt.step()
    return backbone, head
